namespace fs = std::filesystem;
static constexpr const char* HOME_URL = "https://www.google.com";
static constexpr const char* APP_VERSION = "0.4.1";
struct Browser;
struct Tab { Browser* browser{}; WebKitWebView* view{}; GtkWidget* page{}; GtkWidget* label{}; GtkWidget* close{}; std::string url; };
struct Browser { GtkWidget* window{}; GtkWidget* address{}; GtkWidget* back{}; GtkWidget* forward{}; GtkWidget* reload{}; GtkWidget* loading{}; GtkWidget* notebook{}; GtkWidget* new_tab{}; WebKitWebView* view{}; WebKitWebContext* context{}; fs::path profile; fs::path downloads; std::vector<Tab*> tabs; std::string closed_url; };
static Browser app;
static fs::path data_dir(){ const char* b=g_get_user_data_dir(); return fs::path(b?b:".")/"SwiftLife"; }
static std::string trim(std::string v){ v.erase(v.begin(),std::find_if(v.begin(),v.end(),[](unsigned char c){return !std::isspace(c);})); v.erase(std::find_if(v.rbegin(),v.rend(),[](unsigned char c){return !std::isspace(c);}).base(),v.end()); return v; }
static std::string navigate_input(const std::string& raw){ std::string v=trim(raw); if(v.empty())return HOME_URL; if(v=="about:blank")return v; if(v.rfind("https://",0)==0||v.rfind("http://",0)==0)return v; if(v.find(' ')!=std::string::npos||v.find('.')==std::string::npos){ gchar* e=g_uri_escape_string(v.c_str(),nullptr,true); std::string r="https://www.google.com/search?q="+std::string(e?e:""); g_free(e); return r; } return "https://"+v; }
static void save_session(const char* uri){ if(!uri||g_str_has_prefix(uri,"about:"))return; std::error_code ec; fs::create_directories(app.profile,ec); std::ofstream o(app.profile/"last-session.url",std::ios::trunc); if(o)o<<uri<<'\n'; }
static std::string load_session(){ std::ifstream i(app.profile/"last-session.url"); std::string u; std::getline(i,u); u=trim(u); return (u.rfind("https://",0)==0||u.rfind("http://",0)==0)?u:HOME_URL; }
static Tab* current_tab(){ if(!app.notebook)return nullptr; int n=gtk_notebook_get_current_page(GTK_NOTEBOOK(app.notebook)); if(n<0||n>=(int)app.tabs.size())return nullptr; return app.tabs[(size_t)n]; }
static void update_navigation(Browser* b){ if(!b->view)return; gtk_widget_set_sensitive(b->back,webkit_web_view_can_go_back(b->view)); gtk_widget_set_sensitive(b->forward,webkit_web_view_can_go_forward(b->view)); }
static void navigate(Browser* b,const std::string& input){ if(!b->view)return; std::string u=navigate_input(input); webkit_web_view_load_uri(b->view,u.c_str()); }
static void on_address_activate(GtkEntry* e,gpointer d){ Browser* b=(Browser*)d; navigate(b,gtk_entry_get_text(e)); gtk_widget_grab_focus(GTK_WIDGET(b->view)); }
static void on_back(GtkButton*,gpointer d){ Browser* b=(Browser*)d; if(b->view)webkit_web_view_go_back(b->view); }
static void on_forward(GtkButton*,gpointer d){ Browser* b=(Browser*)d; if(b->view)webkit_web_view_go_forward(b->view); }
static void on_reload(GtkButton*,gpointer d){ Browser* b=(Browser*)d; if(b->view)webkit_web_view_reload(b->view); }
static void on_home(GtkButton*,gpointer d){ navigate((Browser*)d,HOME_URL); }
static void on_load_changed(WebKitWebView* v,WebKitLoadEvent e,gpointer d){ Tab* t=(Tab*)d; Browser* b=t->browser; if(e==WEBKIT_LOAD_STARTED&&b->view==v)gtk_widget_show(b->loading); if(e==WEBKIT_LOAD_FINISHED&&b->view==v)gtk_widget_hide(b->loading); if(e==WEBKIT_LOAD_COMMITTED||e==WEBKIT_LOAD_FINISHED){ const char* u=webkit_web_view_get_uri(v); if(u){t->url=u; if(b->view==v){gtk_entry_set_text(GTK_ENTRY(b->address),u);save_session(u);}} if(b->view==v)update_navigation(b); } }
static void on_load_failed(WebKitWebView* v,WebKitLoadEvent,GError*,gpointer d){ Tab* t=(Tab*)d; Browser* b=t->browser; if(b->view==v)gtk_widget_hide(b->loading); const char* u=webkit_web_view_get_uri(v); if(u&&b->view==v)gtk_entry_set_text(GTK_ENTRY(b->address),u); if(b->view==v)update_navigation(b); }
static void on_title_changed(GObject* o,GParamSpec*,gpointer d){ Tab* t=(Tab*)d; const char* title=webkit_web_view_get_title(WEBKIT_WEB_VIEW(o)); std::string s=title&&*title?title:"Yeni sekme"; gtk_label_set_text(GTK_LABEL(t->label),s.c_str()); if(t->browser->view==t->view)gtk_window_set_title(GTK_WINDOW(t->browser->window),(s+" — SwiftLife").c_str()); }
static gboolean on_decide_policy(WebKitWebView*,WebKitPolicyDecision* dec,WebKitPolicyDecisionType type,gpointer){ if(type!=WEBKIT_POLICY_DECISION_TYPE_NAVIGATION_ACTION)return FALSE; auto* a=webkit_navigation_policy_decision_get_navigation_action(WEBKIT_NAVIGATION_POLICY_DECISION(dec)); auto* r=webkit_navigation_action_get_request(a); const char* u=webkit_uri_request_get_uri(r); if(!u)return TRUE; if(g_str_has_prefix(u,"http://")||g_str_has_prefix(u,"https://")||g_str_has_prefix(u,"about:"))return FALSE; webkit_policy_decision_ignore(dec); return TRUE; }
static void select_tab(Browser* b,int page){ if(page<0||page>=(int)b->tabs.size())return; Tab* t=b->tabs[(size_t)page]; b->view=t->view; const char* u=webkit_web_view_get_uri(t->view); gtk_entry_set_text(GTK_ENTRY(b->address),u?u:""); gtk_widget_hide(b->loading); update_navigation(b); gtk_widget_grab_focus(GTK_WIDGET(t->view)); }
static void on_switch_page(GtkNotebook*,GtkWidget*,guint page,gpointer d){ select_tab((Browser*)d,(int)page); }
static void close_tab(Browser* b,Tab* t){ auto it=std::find(b->tabs.begin(),b->tabs.end(),t); if(it==b->tabs.end())return; if(b->tabs.size()==1){webkit_web_view_load_uri(t->view,HOME_URL);return;} b->closed_url=t->url.empty()?HOME_URL:t->url; int idx=(int)std::distance(b->tabs.begin(),it); gtk_notebook_remove_page(GTK_NOTEBOOK(b->notebook),idx); b->tabs.erase(it); delete t; int page=gtk_notebook_get_current_page(GTK_NOTEBOOK(b->notebook)); if(page>=0)select_tab(b,page); }
static void on_tab_close(GtkButton*,gpointer d){ Tab* t=(Tab*)d; close_tab(t->browser,t); }
static GtkWidget* tab_header(Tab* t){ GtkWidget* box=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,4); t->label=gtk_label_new("Yeni sekme"); t->close=gtk_button_new_from_icon_name("window-close-symbolic",GTK_ICON_SIZE_MENU); gtk_widget_set_name(t->close,"tab-close"); gtk_widget_set_tooltip_text(t->close,"Sekmeyi kapat"); gtk_button_set_relief(GTK_BUTTON(t->close),GTK_RELIEF_NONE); gtk_box_pack_start(GTK_BOX(box),t->label,TRUE,TRUE,0); gtk_box_pack_end(GTK_BOX(box),t->close,FALSE,FALSE,0); g_signal_connect(t->close,"clicked",G_CALLBACK(on_tab_close),t); return box; }
static gboolean on_context_menu(WebKitWebView*,WebKitContextMenu* menu,GdkEvent*,WebKitHitTestResult* hit,gpointer){ if(!menu||!hit)return FALSE; bool image=webkit_hit_test_result_context_is_image(hit); bool link=webkit_hit_test_result_context_is_link(hit); bool media=webkit_hit_test_result_context_is_media(hit); if(image){webkit_context_menu_prepend(menu,webkit_context_menu_item_new_from_stock_action_with_label(WEBKIT_CONTEXT_MENU_ACTION_COPY_IMAGE_URL_TO_CLIPBOARD,"Görsel bağlantısını kopyala"));webkit_context_menu_prepend(menu,webkit_context_menu_item_new_from_stock_action_with_label(WEBKIT_CONTEXT_MENU_ACTION_DOWNLOAD_IMAGE_TO_DISK,"⚡ Görseli hemen indir"));webkit_context_menu_prepend(menu,webkit_context_menu_item_new_from_stock_action_with_label(WEBKIT_CONTEXT_MENU_ACTION_OPEN_IMAGE_IN_NEW_WINDOW,"Görseli yeni sekmede aç"));} if(media)webkit_context_menu_prepend(menu,webkit_context_menu_item_new_from_stock_action_with_label(WEBKIT_CONTEXT_MENU_ACTION_DOWNLOAD_VIDEO_TO_DISK,"⚡ Videoyu hemen indir")); if(link){webkit_context_menu_prepend(menu,webkit_context_menu_item_new_from_stock_action_with_label(WEBKIT_CONTEXT_MENU_ACTION_COPY_LINK_TO_CLIPBOARD,"Bağlantıyı kopyala"));webkit_context_menu_prepend(menu,webkit_context_menu_item_new_from_stock_action_with_label(WEBKIT_CONTEXT_MENU_ACTION_DOWNLOAD_LINK_TO_DISK,"⚡ Bağlantıyı hemen indir"));} return FALSE; }
static WebKitWebView* on_create(WebKitWebView*,WebKitNavigationAction*,gpointer d);
static Tab* create_tab(Browser* b,const char* uri,bool switch_to){ Tab* t=new Tab; t->browser=b; t->view=WEBKIT_WEB_VIEW(webkit_web_view_new_with_context(b->context)); gtk_widget_set_hexpand(GTK_WIDGET(t->view),TRUE); gtk_widget_set_vexpand(GTK_WIDGET(t->view),TRUE); t->page=GTK_WIDGET(t->view); GtkWidget* header=tab_header(t); gtk_notebook_append_page(GTK_NOTEBOOK(b->notebook),t->page,header); gtk_notebook_set_tab_reorderable(GTK_NOTEBOOK(b->notebook),t->page,TRUE); b->tabs.push_back(t); g_signal_connect(t->view,"load-changed",G_CALLBACK(on_load_changed),t); g_signal_connect(t->view,"load-failed",G_CALLBACK(on_load_failed),t); g_signal_connect(t->view,"notify::title",G_CALLBACK(on_title_changed),t); g_signal_connect(t->view,"decide-policy",G_CALLBACK(on_decide_policy),b); g_signal_connect(t->view,"create",G_CALLBACK(on_create),b); g_signal_connect(t->view,"context-menu",G_CALLBACK(on_context_menu),b); WebKitSettings* s=webkit_web_view_get_settings(t->view); webkit_settings_set_enable_developer_extras(s,TRUE); webkit_settings_set_enable_smooth_scrolling(s,TRUE); webkit_settings_set_enable_media_stream(s,TRUE); gtk_widget_show_all(t->page); int page=gtk_notebook_page_num(GTK_NOTEBOOK(b->notebook),t->page); if(switch_to){gtk_notebook_set_current_page(GTK_NOTEBOOK(b->notebook),page);select_tab(b,page);} if(uri)webkit_web_view_load_uri(t->view,uri); return t; }
static WebKitWebView* on_create(WebKitWebView*,WebKitNavigationAction*,gpointer d){ Browser* b=(Browser*)d; return create_tab(b,"about:blank",true)->view; }
static std::string safe_filename(const char* uri){ std::string f="download"; if(uri){gchar* p=g_uri_unescape_string(uri,nullptr);const char* s=p?p:uri;const char* slash=strrchr(s,'/');if(slash&&*(slash+1))f=slash+1;g_free(p);} while(!f.empty()&&(f.back()==' '||f.back()=='.'))f.pop_back(); for(char& c:f)if(std::iscntrl((unsigned char)c)||c=='/'||c=='\\'||c==':'||c=='"'||c=='<'||c=='>'||c=='|')c='_'; return f.empty()?"download":f; }
static void on_download_started(WebKitWebContext*,WebKitDownload* dl,gpointer d){ Browser* b=(Browser*)d; std::error_code ec; fs::create_directories(b->downloads,ec); WebKitURIRequest* r=webkit_download_get_request(dl); const char* u=r?webkit_uri_request_get_uri(r):nullptr; std::string f=safe_filename(u); fs::path target=b->downloads/f; for(unsigned n=1;fs::exists(target,ec)&&n<10000;++n)target=b->downloads/(f+" ("+std::to_string(n)+")"); std::string target_str=target.string(); gchar* dest=g_filename_to_uri(target_str.c_str(),nullptr,nullptr); if(dest){webkit_download_set_destination(dl,dest);g_free(dest);} }
static gboolean on_key_press(GtkWidget*,GdkEventKey* e,gpointer d){ Browser* b=(Browser*)d; bool ctrl=(e->state&GDK_CONTROL_MASK)!=0, shift=(e->state&GDK_SHIFT_MASK)!=0, alt=(e->state&GDK_MOD1_MASK)!=0; if(ctrl&&e->keyval==GDK_KEY_l){gtk_widget_grab_focus(b->address);gtk_editable_select_region(GTK_EDITABLE(b->address),0,-1);return TRUE;} if(ctrl&&e->keyval==GDK_KEY_t){create_tab(b,HOME_URL,true);return TRUE;} if(ctrl&&shift&&e->keyval==GDK_KEY_t){create_tab(b,b->closed_url.empty()?HOME_URL:b->closed_url.c_str(),true);return TRUE;} if(ctrl&&e->keyval==GDK_KEY_w){Tab* t=current_tab();if(t)close_tab(b,t);return TRUE;} if(ctrl&&e->keyval==GDK_KEY_Tab){int n=gtk_notebook_get_n_pages(GTK_NOTEBOOK(b->notebook));if(n>1)gtk_notebook_set_current_page(GTK_NOTEBOOK(b->notebook),(gtk_notebook_get_current_page(GTK_NOTEBOOK(b->notebook))+(shift?-1:1)+n)%n);return TRUE;} if(ctrl&&(e->keyval==GDK_KEY_plus||e->keyval==GDK_KEY_equal)){webkit_web_view_set_zoom_level(b->view,std::min(5.0,webkit_web_view_get_zoom_level(b->view)+0.1));return TRUE;} if(ctrl&&e->keyval==GDK_KEY_minus){webkit_web_view_set_zoom_level(b->view,std::max(0.25,webkit_web_view_get_zoom_level(b->view)-0.1));return TRUE;} if(ctrl&&e->keyval==GDK_KEY_0){webkit_web_view_set_zoom_level(b->view,1.0);return TRUE;} if(e->keyval==GDK_KEY_F5){webkit_web_view_reload(b->view);return TRUE;} if(e->keyval==GDK_KEY_F11){gtk_window_fullscreen(GTK_WINDOW(b->window));return TRUE;} if(alt&&e->keyval==GDK_KEY_Left){webkit_web_view_go_back(b->view);return TRUE;} if(alt&&e->keyval==GDK_KEY_Right){webkit_web_view_go_forward(b->view);return TRUE;} return FALSE; }
static void on_new_tab(GtkButton*,gpointer d){create_tab((Browser*)d,HOME_URL,true);}
static GtkWidget* icon_button(const char* icon,const char* tip,GCallback cb,Browser* b){GtkWidget* w=gtk_button_new();gtk_widget_set_name(w,"toolbar-button");gtk_widget_set_tooltip_text(w,tip);gtk_button_set_image(GTK_BUTTON(w),gtk_image_new_from_icon_name(icon,GTK_ICON_SIZE_BUTTON));gtk_button_set_always_show_image(GTK_BUTTON(w),TRUE);g_signal_connect(w,"clicked",cb,b);return w;}
static void apply_css(){const char* css=R"CSS(*{-GtkWidget-focus-line-width:0;}window{background:#0b0f15;}#toolbar{background:#111720;border-bottom:1px solid #293241;padding:8px 10px;}#brand{color:#f6f8fc;font-weight:800;font-size:15px;padding:0 10px 0 2px;}#toolbar-button{background:#171e29;color:#d8dee8;border:1px solid #303b4b;border-radius:10px;padding:5px 7px;min-width:36px;min-height:34px;}#toolbar-button:hover{background:#242d3a;color:#fff;border-color:#46546a;}#toolbar-button:disabled{opacity:.42;}#address{background:#0d131b;color:#eef2f7;border:1px solid #344052;border-radius:13px;padding:8px 14px;min-height:34px;}#address:focus{border-color:#7866e8;}#loading{color:#8f7cff;padding:0 7px;}notebook>header{background:#111720;border-bottom:1px solid #293241;padding:3px 4px;}notebook tab{background:#171e29;color:#bfc8d5;border:1px solid #303b4b;border-radius:8px 8px 0 0;padding:5px 8px;margin:1px;}notebook tab:checked{background:#252f3d;color:#fff;border-color:#4a5870;}#tab-close{background:transparent;color:#8d98a8;border:0;padding:1px;margin:0;}#tab-close:hover{color:#fff;background:#394456;} )CSS"; GtkCssProvider* p=gtk_css_provider_new();gtk_css_provider_load_from_data(p,css,-1,nullptr);gtk_style_context_add_provider_for_screen(gdk_screen_get_default(),GTK_STYLE_PROVIDER(p),GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);g_object_unref(p);}
static void activate(GtkApplication* application,gpointer){std::error_code ec;app.profile=data_dir()/"profile";const char* dd=g_get_user_special_dir(G_USER_DIRECTORY_DOWNLOAD);app.downloads=fs::path(dd?dd:data_dir().c_str())/"SwiftLife";fs::create_directories(app.profile,ec);fs::create_directories(app.downloads,ec);app.window=gtk_application_window_new(application);gtk_window_set_default_size(GTK_WINDOW(app.window),1440,900);gtk_window_set_title(GTK_WINDOW(app.window),"SwiftLife");gtk_window_set_position(GTK_WINDOW(app.window),GTK_WIN_POS_CENTER);gtk_window_set_icon_name(GTK_WINDOW(app.window),"swiftlife");apply_css();g_signal_connect(app.window,"key-press-event",G_CALLBACK(on_key_press),&app);GtkWidget* root=gtk_box_new(GTK_ORIENTATION_VERTICAL,0);gtk_container_add(GTK_CONTAINER(app.window),root);GtkWidget* bar=gtk_box_new(GTK_ORIENTATION_HORIZONTAL,6);gtk_widget_set_name(bar,"toolbar");gtk_box_pack_start(GTK_BOX(root),bar,FALSE,FALSE,0);GtkWidget* brand=gtk_label_new("SwiftLife");gtk_widget_set_name(brand,"brand");gtk_box_pack_start(GTK_BOX(bar),brand,FALSE,FALSE,0);app.back=icon_button("go-previous-symbolic","Geri",G_CALLBACK(on_back),&app);app.forward=icon_button("go-next-symbolic","İleri",G_CALLBACK(on_forward),&app);app.reload=icon_button("view-refresh-symbolic","Yenile",G_CALLBACK(on_reload),&app);GtkWidget* home=icon_button("go-home-symbolic","Ana sayfa",G_CALLBACK(on_home),&app);app.new_tab=icon_button("list-add-symbolic","Yeni sekme",G_CALLBACK(on_new_tab),&app);gtk_box_pack_start(GTK_BOX(bar),app.back,FALSE,FALSE,0);gtk_box_pack_start(GTK_BOX(bar),app.forward,FALSE,FALSE,0);gtk_box_pack_start(GTK_BOX(bar),app.reload,FALSE,FALSE,0);gtk_box_pack_start(GTK_BOX(bar),home,FALSE,FALSE,0);gtk_box_pack_start(GTK_BOX(bar),app.new_tab,FALSE,FALSE,0);app.address=gtk_entry_new();gtk_widget_set_name(app.address,"address");gtk_entry_set_placeholder_text(GTK_ENTRY(app.address),"Adres yazın veya web'de arayın…");gtk_entry_set_icon_from_icon_name(GTK_ENTRY(app.address),GTK_ENTRY_ICON_PRIMARY,"system-search-symbolic");gtk_box_pack_start(GTK_BOX(bar),app.address,TRUE,TRUE,5);g_signal_connect(app.address,"activate",G_CALLBACK(on_address_activate),&app);app.loading=gtk_label_new("●");gtk_widget_set_name(app.loading,"loading");gtk_widget_hide(app.loading);gtk_box_pack_end(GTK_BOX(bar),app.loading,FALSE,FALSE,0);app.notebook=gtk_notebook_new();gtk_notebook_set_scrollable(GTK_NOTEBOOK(app.notebook),TRUE);gtk_notebook_set_show_border(GTK_NOTEBOOK(app.notebook),FALSE);gtk_box_pack_end(GTK_BOX(root),app.notebook,TRUE,TRUE,0);g_signal_connect(app.notebook,"switch-page",G_CALLBACK(on_switch_page),&app);auto* manager=webkit_website_data_manager_new("base-data-directory",app.profile.c_str(),"base-cache-directory",(app.profile/"cache").c_str(),nullptr);app.context=webkit_web_context_new_with_website_data_manager(manager);g_object_unref(manager);webkit_web_context_set_cache_model(app.context,WEBKIT_CACHE_MODEL_WEB_BROWSER);g_signal_connect(app.context,"download-started",G_CALLBACK(on_download_started),&app);create_tab(&app,load_session().c_str(),true);gtk_widget_show_all(app.window);gtk_widget_hide(app.loading);}
int main(int argc,char** argv){for(int i=1;i<argc;++i)if(std::strcmp(argv[i],"--version")==0){g_print("SwiftLife %s (C++17 + GTK3 + WebKitGTK 4.1)\n",APP_VERSION);return 0;}GtkApplication* application=gtk_application_new("com.swiftlife.Browser",G_APPLICATION_DEFAULT_FLAGS);g_signal_connect(application,"activate",G_CALLBACK(activate),nullptr);int status=g_application_run(G_APPLICATION(application),argc,argv);g_object_unref(application);return status;}
